/**************************************************************************/
/**************************************************************************/
/**                                                                       */
/** ThreadX Test                                                          */
/**                                                                       */
/**   TrustZone secure stack services, against a live security unit      */
/**                                                                       */
/**************************************************************************/
/**************************************************************************/

/* The secure stack services are non-secure-callable: the non-secure scheduler
   calls them from an exception handler with the address of a thread control
   block, and they run in secure state. That address comes from the non-secure
   world, so each service has to establish that it names non-secure memory before
   reading or writing through it.

   This test is a bare-metal secure image for an Arm Cortex-M33 with the security
   extension, built and run by scripts/check_trustzone_secure_stack.sh under an
   emulator. It programs the security attribution unit and the memory protection
   controller of the second SSRAM so that one region is genuinely non-secure, then
   calls each service from handler mode, as the scheduler does, with:

     - a pointer whose secure-context field lies on a secure word, which must be
       refused without that word being read or written;
     - a pointer whose secure-context field lies at an unmapped secure address,
       which must be refused without the read that would fault the secure world;
     - a real non-secure thread control block, which must still work end to end.

   The emulator's board is the MPS2 AN505. Its first SSRAM holds this image at
   the secure alias 0x10000000; the second SSRAM is 0x28000000 to 0x283FFFFF on
   the non-secure alias, split here into secure data and a non-secure region.  */

#include <stdio.h>
#include <stdlib.h>
#include <stddef.h>
#include <stdint.h>
#include <string.h>

#include "tx_api.h"
#include "tx_secure_interface.h"


#define TEST_REG32(address)         (*(volatile uint32_t *) (address))

#define TEST_SAU_CTRL               0xE000EDD0u
#define TEST_SAU_RNR                0xE000EDD8u
#define TEST_SAU_RBAR               0xE000EDDCu
#define TEST_SAU_RLAR               0xE000EDE0u
#define TEST_CFSR                   0xE000ED28u
#define TEST_BFAR                   0xE000ED38u

/* Memory protection controller of the AN505's third SSRAM block, secure alias,
   which gates 0x28200000 to 0x283FFFFF.  */
#define TEST_MPC                    0x58009000u
#define TEST_MPC_BLK_MAX            0x010u
#define TEST_MPC_BLK_IDX            0x018u
#define TEST_MPC_BLK_LUT            0x01Cu

#define TEST_NS_REGION              0x28200000u
#define TEST_NS_REGION_SIZE         0x00010000u

/* Secure-attributed, with nothing mapped behind it.  */
#define TEST_UNMAPPED_SECURE        0x18000000u

#define TEST_CONTEXT_OFFSET         offsetof(TX_THREAD, tx_thread_secure_stack_context)
#define TEST_PSPLIM_SENTINEL        0x28001000u

/* Larger than any table of secure contexts the port can be configured with.  */
#define TEST_CONTEXT_OUT_OF_RANGE   0x00010000u


/* Secure words the refused calls aim at.  */
static volatile ULONG   test_secure_nonzero_word = 0x5EC0DE01u;
static volatile ULONG   test_secure_zero_word    = 0u;

static UINT             test_failures;
static UINT             test_checks;


/* A thread pointer whose secure-context field lies on the given address.  */
static TX_THREAD  *test_thread_at(volatile ULONG *field)
{
    return((TX_THREAD *) (((UCHAR *) field) - TEST_CONTEXT_OFFSET));
}


/* Record the outcome of one expectation.  */
static VOID  test_expect(const char *description, ULONG actual, ULONG expected)
{
    test_checks++;
    if (actual != expected)
    {
        printf("FAIL: %s (expected 0x%08lX, got 0x%08lX)\n", description, (unsigned long) expected, (unsigned long) actual);
        test_failures++;
    }
}


/* Read and write the secure process stack limit, which restore programs and save clears.  */
static ULONG  test_psplim_get(VOID)
{
ULONG   value;

    __asm volatile ("MRS     %0, PSPLIM" : "=r" (value));
    return(value);
}

static VOID  test_psplim_set(ULONG value)
{
    __asm volatile ("MSR     PSPLIM, %0" : : "r" (value));
}


/* Make one region of the second SSRAM non-secure: its blocks in the memory
   protection controller, and its addresses in the attribution unit.  */
static VOID  test_non_secure_region_setup(VOID)
{
uint32_t    index;
uint32_t    last;

    last =  TEST_REG32(TEST_MPC + TEST_MPC_BLK_MAX);
    for (index = 0u; index <= last; index++)
    {
        TEST_REG32(TEST_MPC + TEST_MPC_BLK_IDX) =  index;
        TEST_REG32(TEST_MPC + TEST_MPC_BLK_LUT) =  0xFFFFFFFFu;
    }

    TEST_REG32(TEST_SAU_RNR)  =  0u;
    TEST_REG32(TEST_SAU_RBAR) =  TEST_NS_REGION;
    TEST_REG32(TEST_SAU_RLAR) =  ((TEST_NS_REGION + TEST_NS_REGION_SIZE - 32u) & ~0x1Fu) | 1u;
    TEST_REG32(TEST_SAU_CTRL) =  1u;
    __asm volatile ("DSB\n ISB");
}


/* The services insist on being called from an exception handler, so the cases run from the SVC handler.  */
static VOID  test_cases(VOID)
{
UINT        status;
TX_THREAD  *unmapped;
TX_THREAD  *ns_thread;

    unmapped =   (TX_THREAD *) (TEST_UNMAPPED_SECURE - TEST_CONTEXT_OFFSET);
    ns_thread =  (TX_THREAD *) TEST_NS_REGION;

    test_expect("secure stack initialization", _tx_thread_secure_mode_stack_initialize(), TX_SUCCESS);

    /* Allocate reads the context field to see whether a stack exists, then writes
       the new context there; both would reach the secure word.  */
    status =  _tx_thread_secure_mode_stack_allocate(test_thread_at(&test_secure_nonzero_word), 256);
    test_expect("allocate refuses a pointer onto a non-zero secure word", status, TX_PTR_ERROR);
    status =  _tx_thread_secure_mode_stack_allocate(test_thread_at(&test_secure_zero_word), 256);
    test_expect("allocate refuses a pointer onto a zero secure word", status, TX_PTR_ERROR);
    test_expect("...and leaves that word unwritten", test_secure_zero_word, 0u);

    /* Free, save and restore read the context field before anything else; at an
       unmapped secure address that read is a secure bus fault.  */
    status =  _tx_thread_secure_mode_stack_free(unmapped);
    test_expect("free refuses a pointer onto unmapped secure memory", status, TX_PTR_ERROR);

    test_psplim_set(TEST_PSPLIM_SENTINEL);
    _tx_thread_secure_stack_context_save(unmapped);
    test_expect("save returns without acting on a pointer onto unmapped secure memory", test_psplim_get(), TEST_PSPLIM_SENTINEL);
    test_psplim_set(0u);

    _tx_thread_secure_stack_context_restore(unmapped);
    test_expect("restore returns without acting on a pointer onto unmapped secure memory", test_psplim_get(), 0u);

    /* A non-secure thread control block without a secure stack is refused by the
       checks that follow the pointer check.  */
    ns_thread -> tx_thread_secure_stack_context =  TX_NULL;
    ns_thread -> tx_thread_stack_start =           TX_NULL;
    status =  _tx_thread_secure_mode_stack_free(ns_thread);
    test_expect("free refuses a non-secure thread without a secure stack", status, TX_THREAD_ERROR);
    test_psplim_set(TEST_PSPLIM_SENTINEL);
    _tx_thread_secure_stack_context_save(ns_thread);
    test_expect("save leaves a thread without a secure stack alone", test_psplim_get(), TEST_PSPLIM_SENTINEL);
    _tx_thread_secure_stack_context_restore(ns_thread);
    test_expect("restore leaves a thread without a secure stack alone", test_psplim_get(), TEST_PSPLIM_SENTINEL);

    /* So is one whose context names an index past the table of secure contexts.  */
    ns_thread -> tx_thread_secure_stack_context =  (VOID *) TEST_CONTEXT_OUT_OF_RANGE;
    status =  _tx_thread_secure_mode_stack_free(ns_thread);
    test_expect("free refuses a context index past the table", status, TX_THREAD_ERROR);
    _tx_thread_secure_stack_context_save(ns_thread);
    test_expect("save leaves a context index past the table alone", test_psplim_get(), TEST_PSPLIM_SENTINEL);
    _tx_thread_secure_stack_context_restore(ns_thread);
    test_expect("restore leaves a context index past the table alone", test_psplim_get(), TEST_PSPLIM_SENTINEL);
    test_psplim_set(0u);

    /* A real non-secure thread control block goes through the whole cycle.  */
    ns_thread -> tx_thread_secure_stack_context =  TX_NULL;
    ns_thread -> tx_thread_stack_start =           TX_NULL;
    status =  _tx_thread_secure_mode_stack_allocate(ns_thread, 256);
    test_expect("allocate accepts a non-secure thread control block", status, TX_SUCCESS);
    test_expect("...and records its context there", (ULONG) (ns_thread -> tx_thread_secure_stack_context != TX_NULL), TX_TRUE);
    _tx_thread_secure_stack_context_restore(ns_thread);
    test_expect("restore programs that thread's secure stack limit", (ULONG) (test_psplim_get() != 0u), TX_TRUE);
    _tx_thread_secure_stack_context_save(ns_thread);
    test_expect("save clears the secure stack limit", test_psplim_get(), 0u);

    /* A second non-secure thread naming the first one's secure context is not its owner.  */
    (ns_thread + 1) -> tx_thread_secure_stack_context =  ns_thread -> tx_thread_secure_stack_context;
    status =  _tx_thread_secure_mode_stack_free(ns_thread + 1);
    test_expect("free refuses a thread that does not own the secure context", status, TX_THREAD_ERROR);
    test_psplim_set(TEST_PSPLIM_SENTINEL);
    _tx_thread_secure_stack_context_save(ns_thread + 1);
    test_expect("save leaves another thread's secure context alone", test_psplim_get(), TEST_PSPLIM_SENTINEL);
    _tx_thread_secure_stack_context_restore(ns_thread + 1);
    test_expect("restore leaves another thread's secure context alone", test_psplim_get(), TEST_PSPLIM_SENTINEL);
    test_psplim_set(0u);

    status =  _tx_thread_secure_mode_stack_free(ns_thread);
    test_expect("free accepts that thread control block", status, TX_SUCCESS);
    test_expect("...and clears its context", (ULONG) (ns_thread -> tx_thread_secure_stack_context == TX_NULL), TX_TRUE);
}


/* Minimal secure-state runtime: vectors, data initialisation, and fault reporting.  */

extern uint32_t __stack_top__;
extern uint32_t __etext;
extern uint32_t __data_start__;
extern uint32_t __data_end__;
extern uint32_t __bss_start__;
extern uint32_t __bss_end__;
extern VOID     initialise_monitor_handles(VOID);
#ifdef TEST_COVERAGE
extern VOID     __libc_init_array(VOID);
extern VOID     __gcov_dump(VOID);
#endif

int     main(VOID);
VOID    test_reset_handler(VOID);
VOID    _init(VOID);
VOID    _fini(VOID);

VOID  _init(VOID)
{
}

VOID  _fini(VOID)
{
}

static VOID  test_default_handler(VOID)
{
    for (;;)
    {
    }
}

/* A fault means a service touched memory it should have refused.  */
static VOID  test_hard_fault_handler(VOID)
{
    printf("FAIL: secure fault, CFSR 0x%08lX, BFAR 0x%08lX\n",
           (unsigned long) TEST_REG32(TEST_CFSR), (unsigned long) TEST_REG32(TEST_BFAR));
    exit(1);
}

static VOID  test_svc_handler(VOID)
{
    test_cases();
}

__attribute__((section(".vectors"), used))
static VOID (* const test_vectors[16])(VOID) =
{
    (VOID (*)(VOID)) &__stack_top__, test_reset_handler,    test_default_handler, test_hard_fault_handler,
    test_default_handler,            test_default_handler,  test_default_handler, test_default_handler,
    TX_NULL,                         TX_NULL,               TX_NULL,              test_svc_handler,
    test_default_handler,            TX_NULL,               test_default_handler, test_default_handler
};

VOID  test_reset_handler(VOID)
{
    (VOID) memcpy(&__data_start__, &__etext, (size_t) ((uint32_t) &__data_end__ - (uint32_t) &__data_start__));
    (VOID) memset(&__bss_start__, 0, (size_t) ((uint32_t) &__bss_end__ - (uint32_t) &__bss_start__));
    initialise_monitor_handles();
#ifdef TEST_COVERAGE
    __libc_init_array();
    {
    int result = main();
        __gcov_dump();
        exit(result);
    }
#else
    exit(main());
#endif
}

int  main(VOID)
{
    test_non_secure_region_setup();
    __asm volatile ("SVC     #0");

    if (test_failures == 0u)
    {
        printf("SUCCESS! %u expectations\n", test_checks);
        return(0);
    }

    printf("ERROR: %u expectation(s) failed of %u\n", test_failures, test_checks);
    return(1);
}
